// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this) && caller != address(0));
        bool ok;
        vm.prank(caller);
        try c.assertionDisputedCallback(bytes32(uint256(1))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
